import { z } from 'zod';

/**
 * Image credits and derivatives, generated by `pnpm images` into data/generated/images.json from
 * the Wikimedia Commons API (ADR-0002 §4). Never edited by hand. Keyed by Commons file title.
 */
export const LICENSE_FAMILIES = ['public-domain', 'cc0', 'cc-by', 'cc-by-sa'] as const;
export type LicenseFamily = (typeof LICENSE_FAMILIES)[number];

/** Widths written for every image (never wider than the source). */
export const IMAGE_WIDTHS = [320, 640, 1280] as const;
export const IMAGE_FORMATS = ['avif', 'webp'] as const;

const httpsUrl = z.url({ protocol: /^https$/ });

export const imageEntrySchema = z
  .object({
    /** Author as plain text, from the Commons "Artist" field. */
    author: z.string().trim().min(1),
    /** The attribution text the author asked for, when Commons gives one. */
    attribution: z.string().trim().min(1).optional(),
    /** Licence name as Commons states it, e.g. "CC BY-SA 4.0". */
    license: z.string().trim().min(1),
    licenseFamily: z.enum(LICENSE_FAMILIES),
    /** Licence deed. Commons gives none for some public-domain files. */
    licenseUrl: httpsUrl.optional(),
    /** The file's Commons page. */
    sourceUrl: httpsUrl,
    /** Size of the largest derivative, px. */
    width: z.number().int().positive(),
    height: z.number().int().positive(),
    /** Derivative widths written, ascending. */
    widths: z.array(z.number().int().positive()).min(1),
    /** Path under public/ without width and extension, e.g. "images/1a2b3c4d". */
    basename: z.string().regex(/^images\/[0-9a-f]{12}$/),
    /** Tiny blurred preview, inlined. */
    placeholder: z.string().regex(/^data:image\/webp;base64,[A-Za-z0-9+/=]+$/),
    fetched: z.iso.date(),
  })
  .strict()
  .refine((e) => e.licenseFamily === 'public-domain' || e.licenseUrl !== undefined, {
    message: 'A licensed (non-public-domain) image needs a licence URL',
  });
export type ImageEntry = z.infer<typeof imageEntrySchema>;

export const imageManifestSchema = z.record(z.string().regex(/^File:.+$/), imageEntrySchema);
export type ImageManifest = z.infer<typeof imageManifestSchema>;
